import {pythonLink} from './python-links.mjs';
import {VERSION,STORAGE_KEY,STEPS,freshState,restoreState,allocate,DIAGNOSTIC,INSTRUMENTS,gradeQuestions,currentAssessment,chapterComplete,invalidateEvidence} from './model.mjs';

let state=freshState(),storageOK=true;
try{state=restoreState(localStorage.getItem(STORAGE_KEY));localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storageOK=false;}
let page='start';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=id=>state.fields[id]??'';
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',minimumFractionDigits:2}).format(n);
function persist(){state.updated=new Date().toISOString();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('#save-state').textContent=storageOK?'已儲存在此裝置':'無法儲存；離開前請匯出';updateNav();}
function announce(message){$('#announcement').textContent='';requestAnimationFrame(()=>$('#announcement').textContent=message);}
function mark(id){state.done[id]=true;persist();}
function updateNav(){const n=STEPS.filter(([id])=>state.done[id]).length;$('#navigation').innerHTML=STEPS.map(([id,title,min],i)=>`<a href="#${id}" ${id===page?'aria-current="step"':''} class="${state.done[id]?'done':''}"><span class="step-icon" aria-hidden="true">${state.done[id]?'✓':String(i+1).padStart(2,'0')}</span><span>${title}<small>${min} 分鐘${state.done[id]?'・已完成':''}</small></span></a>`).join('');$('#progress-label').textContent=`${n}／7 步驟已完成`;$('#progress-percent').textContent=`${Math.round(n/7*100)}%`;$('#progress').value=n;$('#progress').textContent=`${n}／7 步驟已完成`;}
function heading(eyebrow,title,lead){return `<div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="lead">${lead}</p>`;}
function bottom(){const i=STEPS.findIndex(([id])=>id===page);return `<div class="bottom-nav">${i>0?`<a href="#${STEPS[i-1][0]}">← 上一步</a>`:'<span class="mini">沒有計時，依自己的步調學習。</span>'}${i<STEPS.length-1?`<div><small>下一步</small><a href="#${STEPS[i+1][0]}">${STEPS[i+1][1]}</a></div>`:'<a href="#start">回到本章總覽</a>'}</div>`;}
function field(id,label,placeholder='',type='text'){return `<label class="field" for="${id}">${label}</label>${type==='textarea'?`<textarea id="${id}" data-save placeholder="${esc(placeholder)}">${esc(val(id))}</textarea>`:`<input type="${type}" id="${id}" data-save value="${esc(val(id))}" placeholder="${esc(placeholder)}">`}`;}
function choices(q,prefix=''){const name=prefix+q.id;return `<fieldset class="question"><legend>${esc(q.title)}</legend><div class="options">${q.options.map((o,i)=>`<label class="option"><input type="radio" name="${name}" value="${i}" data-save ${String(val(name))===String(i)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div></fieldset>`;}
function confidence(id){return `<label class="field" for="${id}">你對答案有多大信心？ <small>僅供反思，信心不影響分數。</small></label><select id="${id}" data-save><option value="">可自行選擇</option>${['仍不確定','有些信心','有信心'].map(s=>`<option ${val(id)===s?'selected':''}>${s}</option>`).join('')}</select>`;}
function feedback(id,text,error=false){const el=$('#'+id);el.innerHTML=text;el.className=`feedback${error?' error':''}`;el.setAttribute('tabindex','-1');el.focus();announce(el.textContent);}
function go(id){location.hash=id;}
function savedCheck(id,label){return `<label class="option"><input type="checkbox" id="${id}" data-save ${val(id)?'checked':''}><span>${label}</span></label>`;}

const views={
start(){return heading('第 1 章｜約 3 小時','先提出一個<br>能檢驗的問題','在公式與程式之前，先把投資想法轉成有規則、有比較對象、有證據的研究問題。')+`<div class="pill-row"><span class="pill">適合初學者</span><span class="pill">不需安裝</span><span class="pill">可隨時暫停</span></div><section class="panel" id="setup-panel"><h2>先準備學習環境（15 分鐘）</h2><ol><li>使用現代瀏覽器、紙筆及計算機；不需投資帳戶、券商連線或程式經驗。大螢幕較方便閱讀表格。既有私人網站可能需要原本的存取登入。</li><li>輸入下方的工作區名稱，再切換步驟回來確認資料有保留。避免姓名、帳號及個人財務資訊。</li><li>若 JavaScript、儲存或版面造成困難，使用<a href="chapter-guide.html">完整文字與紙筆路線</a>。</li><li>本章 180 分鐘為設計估計，包含準備、練習、檢核與修正；尚未經學習者試學驗證，沒有倒數計時。</li></ol>${field('workspace','工作區名稱','例如：我的第一個金融問題')}${savedCheck('setupConfirmed','我能輸入內容，也知道匯出及「隱私與重設」在哪裡。')}<div class="actions"><button data-action="setup">確認準備，開始學習</button><button class="secondary" data-action="export">試著匯出進度</button></div><div id="setup-feedback" class="feedback" role="status"></div></section><section class="panel"><h2>本章要帶走的三項能力</h2><ul><li>分辨存款、債券、股票與基金各代表什麼權利。</li><li>選擇符合問題的基準，使用相同日期與成本比較。</li><li>用配置、情境、衡量準則與限制完成研究卡。</li></ul><p>學習答案保存在此瀏覽器。匯出檔是個人學習紀錄，不能匯入還原，也不會跨裝置同步。完成條件包括診斷、四項分類、範例、兩種情境的實驗與手算、獨立檢核、回應回饋及研究卡。這是形成性自學，不提供正式認證。</p></section>`;},
readiness(){return heading('第 2 步｜30 分鐘','找出自己的起點','先試三題，再依回饋選擇補強或延伸。診斷不計入成績；錯誤能指出該練習的地方。')+`<section class="panel"><h2>先作答，再讀解釋</h2>${DIAGNOSTIC.map(q=>choices(q)).join('')}${confidence('diagnosticConfidence')}<button data-action="diagnostic">檢查我的起點</button><div id="diagnostic-feedback" class="feedback" role="status">${state.diagnostic?diagnosticFeedback():''}</div></section><section class="panel"><h2>補強：百分比要相對於起始值</h2><p>£200 變成 £210，增加 £10；10÷200=0.05，也就是 5%。金額變動與百分比不同。組合的權重是投入資金的比例；25% 資金賺 8%、75% 賺 0%，整體為 0.25×8%+0.75×0%=2%。£ 代表英鎊，並非新臺幣。</p><p>換個例子：£400 成長到 £420，增加百分比是多少？不需輸入 % 符號。</p>${field('bridgeAnswer','增加的百分比','','number')}<button data-action="bridge" class="secondary">檢查計算</button><div id="bridge-feedback" class="feedback" role="status"></div><details><summary>逐步提示</summary><p>先算期末減期初，再除以 £400，最後乘 100。</p></details></section><section class="panel"><h2>延伸：相同金額，不同分母</h2><p>£100 跌到 £80，再回到 £100。先各算一次百分比，解釋為什麼不能直接相加。</p>${field('extensionReason','寫下計算與理由','先下跌……再上漲……','textarea')}<details><summary>做完後比對</summary><p>下跌 20%；回升為 25%，因為新的起點是 £80。最終回到原值，複利報酬率為 0%。延伸題為選做且不計分。</p></details><p>建議分配：嘗試 5 分鐘、補強或延伸 20 分鐘、修正與反思 5 分鐘；需要時可多花時間。</p></section>`;},
markets(){return heading('第 3 步｜35 分鐘','你真正持有的是什麼？','先看經濟權利，再看商品名稱；所有權、還款承諾與集合工具並不相同。')+`<div class="table-wrap"><table><caption>四種基本金融工具</caption><thead><tr><th>工具</th><th>持有的權利</th><th>需要記住的風險</th></tr></thead><tbody><tr><th>現金存款</th><td>依帳戶條款存放在銀行的餘額。</td><td>通膨侵蝕購買力；提領、銀行與存款保障依所在地及帳戶而異。</td></tr><tr><th>債券</th><td>借款給發行人，通常有利息與還本承諾。</td><td>可能違約；利率上升時，市價可能下跌。</td></tr><tr><th>股票</th><td>企業的部分所有權。</td><td>股利與轉售獲利沒有保證。</td></tr><tr><th>基金／ETF</th><td>持有多項投資的集合工具；ETF 在交易所買賣。</td><td>風險來自標的、集中程度、費用及結構；基金不等於安全。</td></tr></tbody></table></div><section class="panel"><h2>範例：債券基金不等於一張債券</h2><p>單一債券可能承諾到期還本，但仍有違約風險。債券基金的持有組合持續變動，基金單位通常沒有對應於你指定日期的固定贖回價值。兩者都有債務曝險，但包裝改變了持有的權利。</p><p>先預測：買三檔基金，是否一定比一檔更分散？需要檢查哪些資訊？</p><details><summary>比較你的理由</summary><p>應看底層持有標的與共同曝險；三檔基金可能持有相同公司或集中於同一產業。商品名稱的數量不足以判斷分散程度。</p></details></section><section class="panel"><h2>練習：依權利分類</h2><p>四題都答對即可完成本練習。看過回饋後可以修改，不扣分。</p>${INSTRUMENTS.map(q=>`<label class="field" for="instrument-${q.id}">${q.name}</label><select id="instrument-${q.id}" data-save><option value="">選擇工具</option>${[['cash','現金存款'],['bond','債券'],['share','股票'],['fund','基金／ETF']].map(([v,l])=>`<option value="${v}" ${val('instrument-'+q.id)===v?'selected':''}>${l}</option>`).join('')}</select>`).join('')}<button data-action="classify">檢查分類</button><div id="classification-feedback" class="feedback" role="status">${state.classification?classificationFeedback():''}</div></section><section class="panel"><h2>換個情境，向朋友解釋</h2><p>朋友說：「我的科技 ETF 持有 30 家公司，所以不可能虧很多。」用兩句話回應，分清楚工具與標的，指出一項共同曝險，再依檢核表修改一句。</p>${field('marketTransfer','你的回應','ETF 是……持有標的可能……','textarea')}<details><summary>寫完後自我檢查</summary><p>應說明 ETF 是集合工具、公司可能共享科技產業風險，且分散不能保證不虧損。不要承諾特定保護幅度。</p></details><p>建議：閱讀 10 分鐘、預測 5 分鐘、分類與修正 10 分鐘、解釋 10 分鐘。</p></section>`;},
case(){return heading('第 4 步｜25 分鐘','與什麼比較？','基準是事先指定的比較起點，應符合研究問題，不能為了讓結果好看才挑選。')+`<section class="panel"><h2>完整範例：比較較保守的配置</h2><p>Maya 問：在提供的一年情境中，50% 現金／40% 債券／10% 股票，是否比 20%／40%／40% 的基準在壓力時虧得少？平穩時又放棄多少報酬？這是描述配置的取捨，不是證明某個策略普遍較好。</p><p>各自以 £1,000 開始，期初買進後持有一年，不在年中再平衡。以下是原創假設教學資產；手續費、交易成本與稅為零，後續章節才引入成本。</p><table><caption>虛構的一年總報酬率，非市場觀測</caption><tr><th>資產</th><th>平穩情境</th><th>壓力情境</th></tr><tr><th>現金</th><td>+2%</td><td>+1%</td></tr><tr><th>債券</th><td>+3%</td><td>−5%</td></tr><tr><th>股票</th><td>+8%</td><td>−20%</td></tr></table><h3>平穩情境的基準</h3><p>0.20×2%+0.40×3%+0.40×8%=4.8%；期末 £1,000×1.048=£1,048。</p><h3>相同情境的保守配置</h3><p>0.50×2%+0.40×3%+0.10×8%=3.0%；期末 £1,030。比基準少 1.8 個百分點，金額少 £18，並不是 £1.80。</p><p>不公平比較包括：日期不同、未標準化的起始資金不同、成本規則偷偷改變，或看到結果後才挑基準。本例刻意比較不同風險配置，風險差異就是問題的一部分。</p></section><section class="panel"><h2>先預測，再完成壓力情境</h2><p>用上表的負報酬計算兩種配置，保留負號，最後算報酬率相差多少個百分點。</p>${field('casePrediction','預測及理由','我預期……因為……','textarea')}${field('caseGap','壓力虧損差距（正數，百分點）','','number')}<button data-action="case-check">檢查範例</button><div id="case-feedback" class="feedback" role="status"></div><details><summary>提示</summary><p>基準先算 0.20×1+0.40×(−5)+0.40×(−20)，再把權重換成 0.50、0.40、0.10。</p></details></section><section class="panel"><h2>好的問題包含什麼？</h2><ol><li>可重現的規則或比較方式。</li><li>事先聲明且符合曝險的基準。</li><li>相同期間、情境及可衡量證據。</li><li>可能讓結論無法推廣的假設與限制。</li></ol><p>「什麼投資最好？」沒有交代以上決定。「規則 A 在提供期間、扣除相同成本後，是否比相符基準降低最大回撤？」才指出證據。最大回撤是從先前組合高點下跌的最大幅度，後續會實際計算。</p></section>`;},
lab(){const r=state.labRuns.at(-1);return heading('第 5 步｜35 分鐘','先預測，再測試','只改配置，不改過去。比較同一組非基準權重在兩種情境的結果。')+`<p>沿用範例的一年報酬：平穩為 2%、3%、8%；壓力為 1%、−5%、−20%。起始 £1,000，買進持有、不再平衡、成本與稅皆為零。</p><section class="panel"><h2>1. 寫下預測</h2>${field('labPrediction','預期結果與理由','我預期……因為……','textarea')}${confidence('labConfidence')}<h2>2. 設定期初權重</h2><p>三項各介於 0 至 100，合計 100%；這不是最佳或個人適合配置的建議。</p><div class="allocation">${[['weightCash','現金',20],['weightBond','債券',40],['weightShare','股票',40]].map(([id,label,def])=>`<label class="field" for="${id}">${label}（%）<input id="${id}" data-save type="number" min="0" max="100" value="${esc(state.fields[id]??def)}"></label>`).join('')}</div><label class="field" for="regime">情境</label><select id="regime" data-save><option value="steady" ${val('regime')==='steady'?'selected':''}>平穩年度</option><option value="stress" ${val('regime')==='stress'?'selected':''}>壓力年度</option></select><div class="actions"><button data-action="run">執行比較</button><button class="secondary" data-action="baseline">重設為基準權重</button></div><div id="lab-feedback" class="feedback" role="status"></div><div id="lab-result">${r?labResult(r):''}</div></section><section class="panel"><h2>3. 手算檢查最新結果</h2><p>先用各權重乘報酬並加總，再算 £1,000×(1+報酬率÷100)，不要只抄畫面的答案。</p>${field('handCheck','期末金額（英鎊，不含符號）','','number')}<button data-action="hand-check">檢查手算</button><div id="hand-feedback" class="feedback" role="status"></div><h2>4. 換情境並評論</h2><p>相同非基準配置須各跑一次平穩與壓力情境，以隔離情境變化。比較取捨與假設，不挑最好看的一次。</p>${field('labReflection','預測是否成立？你會如何修正？','比較兩個結果，並指出一項限制。','textarea')}<div class="actions"><button data-action="complete-lab">儲存實驗反思</button><button data-action="download-csv" class="secondary">下載所有試算 CSV</button></div><div id="lab-completion" class="feedback" role="status"></div></section><section class="panel"><h2>完整實驗紀錄</h2><p>重設權重不會清除試算；所有結果都保留在此裝置，匯出不會只保留有利結果。</p><div class="table-wrap">${runTable()}</div></section><p>建議：預測 5 分鐘，試算及手算 15 分鐘，跨情境比較 10 分鐘，修正 5 分鐘。</p>`;},
assessment(){const qs=currentAssessment(state),attempt=state.assessmentAttempts.at(-1),set=Number(val('assessmentSet')||0);return heading('第 6 步｜25 分鐘','換個例子，獨立檢查','先獨立作答，再看回饋並修正。可用計算機，沒有時間限制。')+`<section class="panel"><p>至少答對 5／6 題，且第 3、6 題關鍵題都須正確。完成後還要儲存回饋回應。這是形成性自學，不是保密考試或正式證照。</p><p>目前累積 ${state.assessmentAttempts.length} 次提交；切換會換題並清空本次答案，先前紀錄仍保留。只有 A、B 兩組，繼續切換會重複。</p>${qs.map((q,i)=>choices({...q,title:`${i+1}. ${q.title}${q.critical?'【關鍵題】':''}`},'quiz-')).join('')}${confidence('assessmentConfidence')}<div class="actions"><button data-action="grade">檢查答案</button><button data-action="new-case" class="secondary">切換到題組 ${set%2===0?'B':'A'}</button></div><div id="assessment-feedback" class="feedback" role="status">${attempt&&attempt.set===set&&!state.fields.assessmentDirty?assessmentFeedback(attempt):''}</div></section><section class="panel"><h2>讓回饋改變下一步</h2><p>回到相關範例，寫下想法如何改變，再修正並重新提交。若第一次就通過，指出一個容易誤判的假設或選項，並說明理由。</p>${field('assessmentRevision','我的修正或反思','原本我認為……定義或證據顯示……下次我會……','textarea')}<button data-action="save-revision">儲存回饋回應</button><div id="revision-feedback" class="feedback" role="status"></div></section>`;},
finish(){return heading('第 7 步｜15 分鐘','帶著研究問題往下走','把規則、基準、期間、證據與限制放進同一張研究卡。')+`<section class="panel"><h2>先指定證據，再看結果</h2><p>使用實驗中試過的非基準配置。本卡評估的是教學情境，不是個人投資決定。文字由你自行檢視；系統只檢查完整性與算術，不能判斷研究主張品質。</p>${field('planRule','1. 規則／配置','例如：期初買進 50% 現金、40% 債券、10% 股票，持有一年。','textarea')}${field('planBenchmark','2. 基準與選擇理由','指定 20／40／40 的課堂基準，解釋要觀察的取捨。','textarea')}${field('planEvidence','3. 期間及可衡量證據','使用兩個一年情境，交代報酬率或期末金額比較。','textarea')}${field('planLimits','4. 限制及可能推翻預測的結果','指出零成本或合成資料假設，以及會削弱主張的證據。','textarea')}${savedCheck('planC1','已指定可重現的配置與基準，而非只問「最佳投資」。')}${savedCheck('planC2','比較採用相同情境、起始金額與成本規則。')}${savedCheck('planC3','也會報告不利結果，並指出限制。')}<details><summary>草稿完成後再看範例</summary><p>我將比較買進持有 50／40／10 與固定 20／40／40，兩個虛構一年情境都從 £1,000 開始。我會報告總報酬率與百分點差，預期壓力虧損較小、平穩報酬較低。真實成本或不同報酬可能改變結果，兩個情境不能證明未來績效。</p></details>${field('planRevision','看過準則或範例後，你改了什麼？','指出具體修改，以及為什麼更容易檢驗。','textarea')}<div class="actions"><button data-action="save-plan">儲存研究卡</button><button data-action="export" class="secondary">匯出進度與研究卡</button></div><div id="plan-feedback" class="feedback" role="status"></div></section><section class="panel"><h2>檢查學習證據</h2>${STEPS.map(([id,title])=>`<div class="status-row"><a href="#${id}">${title}</a><span>${state.done[id]?'✓ 已完成':'待完成'}</span></div>`).join('')}<p>${chapterComplete(state)?'本章完成。請先匯出紀錄，再進入金融數學。':'可以回到任何未完成步驟；完成取決於學習證據，不是瀏覽時間。'}</p><a href="chapter-02/">前往第 2 章：金融數學</a></section><details><summary>詞彙與延伸閱讀</summary><p>基準：事先指定的比較起點。配置：資金如何分配。報酬率：相對起始價值的盈虧。百分點：兩個百分比之差。合成資料：為特定目的設計的資料。最大回撤：從先前高點下跌的最大幅度。</p><p><a href="https://www.investor.gov/introduction-investing/investing-basics/investment-products">Investor.gov 金融商品（英文）</a>、<a href="https://www.investor.gov/introduction-investing/getting-started/asset-allocation">資產配置與分散（英文）</a>。外部閱讀為選讀，網站有自己的隱私政策。</p></details>`;}
};

function diagnosticFeedback(){return `<strong>${state.diagnostic.score}／3｜不計分起點檢查</strong><ul>${DIAGNOSTIC.map(q=>`<li>${esc(q.feedback[state.diagnostic.answers[q.id]])}</li>`).join('')}</ul><p>${state.diagnostic.score===3?'可以試延伸題；也可隨時回來補強。':'先練補強，再試新的計算；需要時重讀解釋。'}</p>`;}
function classificationFeedback(){return `<strong>${state.classification.score}／4 題正確</strong><ul>${INSTRUMENTS.map(q=>`<li>${state.classification.answers[q.id]===q.answer?'✓ '+q.explanation:'重新檢查「'+q.name+'」：'+q.hint}</li>`).join('')}</ul><p>${state.classification.score===4?'接著練習解釋 ETF 的主張。':'修改相關選項，再次檢查；練習修正不扣分。'}</p>`;}
function labResult(r){return `<h3>第 ${state.labRuns.indexOf(r)+1} 次試算｜${r.regime==='stress'?'壓力':'平穩'}情境</h3><div class="bars" aria-hidden="true">${r.weights.map((w,i)=>`<span class="${['bar-cash','bar-bond','bar-share'][i]}" style="width:${w}%"></span>`).join('')}</div><p>現金 ${r.weights[0]}%、債券 ${r.weights[1]}%、股票 ${r.weights[2]}%</p><div class="metrics"><div class="metric"><span>組合報酬率</span><strong>${r.gross.toFixed(2)}%</strong></div><div class="metric"><span>£1,000 的期末金額</span><strong>${money(r.ending)}</strong></div><div class="metric"><span>相對基準的差距</span><strong>${(r.gross-r.benchmark).toFixed(2)} 個百分點</strong></div></div><p>基準報酬率 ${r.benchmark.toFixed(2)}%；百分點差＝你的報酬率−基準報酬率。不含真實市場資料及費用。</p>`;}
function runTable(){return state.labRuns.length?`<table><caption>所有假設試算；基準為 20% 現金／40% 債券／40% 股票</caption><tr><th>次數</th><th>情境</th><th>現金／債券／股票權重</th><th>報酬率</th><th>期末英鎊金額</th><th>基準報酬率</th></tr>${state.labRuns.map((r,i)=>`<tr><td>${i+1}</td><td>${r.regime==='stress'?'壓力':'平穩'}</td><td>${r.weights.join('／')}%</td><td>${r.gross.toFixed(2)}%</td><td>${money(r.ending)}</td><td>${r.benchmark.toFixed(2)}%</td></tr>`).join('')}</table>`:'<p class="empty">尚無試算；先寫下預測，再執行比較。</p>';}
function assessmentFeedback(a){return `<strong>${a.score}／${a.total}｜${a.passed?'數值檢核通過':'請再練習'}</strong><p>${a.passed?'請在下方儲存回饋回應，才會完成此步驟。':'至少答對 5／6 題，且第 3、6 題均須正確。讀過理由後修正並重新提交。'}</p><ol>${a.questions.map((q,i)=>`<li><strong>${a.details[i].correct?'正確':'重新檢查'}：</strong>${esc(q.why)}</li>`).join('')}</ol>`;}
function exportProgress(){const payload={chapter:'量化金融基礎｜第 1 章',version:VERSION,exportedAt:new Date().toISOString(),...state,completion:chapterComplete(state),notice:'形成性自學紀錄；文字回答由學習者自我檢視，不授予證書或經驗證的能力認定。'};download('qf-chapter-01-progress.json',JSON.stringify(payload,null,2),'application/json');announce('已下載進度檔，內含儲存答案與所有提交紀錄。');}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function render(focus=true){const target=location.hash.slice(1);if(target==='lesson'){ $('#lesson').focus();return;}page=STEPS.some(([id])=>id===target)?target:(STEPS.some(([id])=>id===state.lastPage)?state.lastPage:'start');state.lastPage=page;$('#lesson').innerHTML=views[page]()+pythonLink(1,page)+bottom();persist();document.title=`${STEPS.find(([id])=>id===page)[1]} ｜量化金融基礎`;if(focus){$('#lesson').focus();window.scrollTo({top:0,behavior:'instant'});}}

document.addEventListener('input',e=>{const el=e.target;if(!el.matches('[data-save]'))return;const id=el.name||el.id;state.fields[id]=el.type==='checkbox'?el.checked:el.value;const feedbackId=invalidateEvidence(state,id);if(feedbackId&&$('#'+feedbackId))$('#'+feedbackId).textContent='內容已修改，請重新檢查或儲存此步驟。';persist();});
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
if(action==='begin'){$('#setup-panel').scrollIntoView({behavior:'instant',block:'start'});$('#workspace').focus();}
if(action==='export')exportProgress();
if(action==='setup'){if(!val('setupConfirmed'))return feedback('setup-feedback','確認能輸入文字，且找到匯出與重設功能後，勾選準備確認。',true);mark('start');go('readiness');}
if(action==='diagnostic'){const answers=Object.fromEntries(DIAGNOSTIC.map(q=>[q.id,val(q.id)===''?null:Number(val(q.id))]));if(Object.values(answers).some(v=>v===null))return feedback('diagnostic-feedback','請為每個起點問題選一個答案；此診斷不計分。',true);state.diagnostic={answers,score:DIAGNOSTIC.filter(q=>answers[q.id]===q.answer).length};mark('readiness');feedback('diagnostic-feedback',diagnosticFeedback());}
if(action==='bridge'){const n=Number(val('bridgeAnswer'));feedback('bridge-feedback',val('bridgeAnswer')!==''&&Math.abs(n-5)<.001?'正確：(420−400)÷400×100=5%。試著解釋為什麼分母是起始值。':'先找出 £20 的變動，再除以起始 £400 並乘 100，輸入百分比數值。',!(val('bridgeAnswer')!==''&&Math.abs(n-5)<.001));}
if(action==='classify'){const answers=Object.fromEntries(INSTRUMENTS.map(q=>[q.id,val('instrument-'+q.id)]));if(Object.values(answers).some(v=>!v))return feedback('classification-feedback','四項權利都選好分類後，再檢查。',true);state.classification={answers,score:INSTRUMENTS.filter(q=>answers[q.id]===q.answer).length};if(state.classification.score===4)mark('markets');else persist();feedback('classification-feedback',classificationFeedback());}
if(action==='case-check'){const correct=val('caseGap')!==''&&Math.abs(Number(val('caseGap'))-6.3)<.01;if(!val('casePrediction').trim())return feedback('case-feedback','先寫下預測及理由，再計算差距。',true);if(!correct)return feedback('case-feedback','基準為 −9.8%，Maya 配置為 −3.5%。相減後輸入正的百分點差，注意不是英鎊金額。',true);mark('case');feedback('case-feedback','正確：壓力情境相差 6.3 個百分點。Maya 虧 £35、基準虧 £98，但平穩時少賺 £18。這是兩個虛構情境的取捨，不代表必然優於其他配置。');}
if(action==='baseline'){for(const [id,n] of [['weightCash',20],['weightBond',40],['weightShare',40]])state.fields[id]=String(n);persist();render(false);$('#weightCash').focus();announce('權重已重設為現金 20%、債券 40%、股票 40%；實驗紀錄仍保留。');}
if(action==='run'){if(!val('labPrediction').trim())return feedback('lab-feedback','執行前先寫下預測；一句預期結果與理由即可。',true);try{const weights=['weightCash','weightBond','weightShare'].map(id=>$('#'+id).value);const result=allocate(weights,$('#regime').value);state.labRuns.push({...result,prediction:val('labPrediction'),timestamp:new Date().toISOString()});state.fields.handVerified=false;state.fields.handCheck='';delete state.done.lab;persist();render(false);feedback('lab-feedback',`已記錄第 ${state.labRuns.length} 次試算。閱讀結果後，請以手算檢查。`);}catch(err){feedback('lab-feedback',esc(err.message),true);}}
if(action==='hand-check'){const r=state.labRuns.at(-1);if(!r)return feedback('hand-feedback','請先執行比較，才有結果可檢查。',true);const correct=val('handCheck')!==''&&Math.abs(Number(val('handCheck'))-r.ending)<.011;if(!correct)return feedback('hand-feedback','使用最新試算的權重與報酬，先加總加權報酬率，除以 100 後加 1，再乘 £1,000；英鎊金額取小數兩位。',true);state.fields.handVerified=true;persist();feedback('hand-feedback','手算符合最新結果。請在反思中解釋加權計算；數值相符不等於研究主張成立。');}
if(action==='complete-lab'){const paired=state.labRuns.some(a=>a.weights.some((v,i)=>Math.abs(v-[20,40,40][i])>.001)&&state.labRuns.some(b=>b.regime!==a.regime&&b.weights.every((v,i)=>Math.abs(v-a.weights[i])<.001)));if(!paired)return feedback('lab-completion','請用同一組非基準權重各執行平穩與壓力情境，以固定配置、只比較情境差異。',true);if(!state.fields.handVerified)return feedback('lab-completion','完成實驗前，先手算檢查最新一次的期末金額。',true);if(val('labReflection').trim().length<30)return feedback('lab-completion','反思至少 30 個字元，比較兩個情境並指出限制。長度只檢查完整性，請依範例自我檢視理由。',true);mark('lab');feedback('lab-completion','已儲存雙情境、手算與反思。回顧預測，必要時做一項具體修正。');}
if(action==='download-csv'){if(!state.labRuns.length)return feedback('lab-completion','下載前請先執行比較。',true);download('qf-chapter-01-runs.csv','run,scenario,cash_weight_pct,bond_weight_pct,share_weight_pct,return_pct,ending_gbp,benchmark_return_pct,fee_gbp\n'+state.labRuns.map((r,i)=>[i+1,r.regime,...r.weights,r.gross.toFixed(6),r.ending.toFixed(2),r.benchmark,0].join(',')).join('\n'),'text/csv');announce('已下載全部實驗的 CSV。');}
if(action==='grade'){const questions=currentAssessment(state);const answers=Object.fromEntries(questions.map(q=>[q.id,val('quiz-'+q.id)===''?null:Number(val('quiz-'+q.id))]));if(Object.values(answers).some(v=>v===null))return feedback('assessment-feedback','請先完成六題；沒有時間限制。',true);const result=gradeQuestions(questions,answers);state.assessmentAttempts.push({...result,answers,questions,set:Number(val('assessmentSet')||0),timestamp:new Date().toISOString()});state.fields.assessmentDirty=false;state.fields.revisionSaved=false;delete state.done.assessment;persist();feedback('assessment-feedback',assessmentFeedback(state.assessmentAttempts.at(-1)),!result.passed);}
if(action==='new-case'){state.fields.assessmentSet=String(Number(val('assessmentSet')||0)+1);for(let i=1;i<=6;i++)state.fields['quiz-a'+i]='';state.fields.assessmentRevision='';state.fields.revisionSaved=false;delete state.done.assessment;persist();render();announce('另一組題目已備妥，先前作答仍保留在匯出紀錄。');}
if(action==='save-revision'){const a=state.assessmentAttempts.at(-1);if(!a||a.set!==Number(val('assessmentSet')||0)||state.fields.assessmentDirty)return feedback('revision-feedback','請先提交此題組目前的答案，再回應該次回饋。',true);if(val('assessmentRevision').trim().length<30)return feedback('revision-feedback','至少寫 30 個字元，指出具體修正或反思，說明改變了什麼及原因。',true);state.fields.revisionSaved=true;a.revision=val('assessmentRevision');if(a.passed)mark('assessment');else persist();feedback('revision-feedback',a.passed?'回饋回應已儲存，獨立檢核完成。':'回應已儲存，請修正題目並重新提交，以符合通過條件。');}
if(action==='save-plan'){const ids=['planRule','planBenchmark','planEvidence','planLimits','planRevision'];if(ids.some(id=>val(id).trim().length<20))return feedback('plan-feedback','五個文字欄位（含修正）各至少 20 個字元。此為完整性檢查，品質仍需依準則自我檢視。',true);if(!['planC1','planC2','planC3'].every(id=>val(id)===true))return feedback('plan-feedback','請逐項檢視並勾選三個準則，必要時修正研究卡。',true);state.plan=Object.fromEntries(ids.map(id=>[id,val(id)]));mark('finish');render(false);feedback('plan-feedback',chapterComplete(state)?'本章完成，研究卡與學習證據已儲存在此裝置，請匯出留存。':'研究卡已儲存，請看下方清單補齊其他證據。');}
});
$('#export-sidebar').addEventListener('click',exportProgress);
$('#privacy-button').addEventListener('click',()=>$('#privacy-dialog').showModal());
$('#close-privacy').addEventListener('click',()=>$('#privacy-dialog').close());
$('#reset-progress').addEventListener('click',()=>{if(!confirm('要刪除此瀏覽器中本章的答案、嘗試及進度嗎？已匯出檔案不會刪除。'))return;state=freshState();try{localStorage.removeItem(STORAGE_KEY);}catch{}$('#privacy-dialog').close();persist();location.hash='start';render();announce('此裝置的本章進度已重設。');});
window.addEventListener('hashchange',()=>render());
render(false);
